#include "sortlab/extended_algorithms.hpp"
#include "sortlab/workloads.hpp"
#include <algorithm>
#include <chrono>
#include <cstdint>
#include <iostream>
#include <numeric>
#include <stdexcept>
#include <string>
#include <string_view>
#include <vector>
using namespace sortlab;
struct Variant{std::string family;std::size_t cutoff;};
static std::vector<std::string> split(std::string_view x){std::vector<std::string>o;std::size_t p=0;while(p<=x.size()){auto e=x.find(',',p);auto t=x.substr(p,e==std::string_view::npos?x.size()-p:e-p);if(t.empty())throw std::runtime_error("empty item");o.emplace_back(t);if(e==std::string_view::npos)break;p=e+1;}return o;}
static std::vector<std::size_t> nums(std::string_view x){std::vector<std::size_t>o;for(auto&s:split(x))o.push_back(static_cast<std::size_t>(std::stoull(s)));return o;}
template<bool C> static void run_variant(const Variant&v,std::vector<Value>&a,Stats&s){if(v.family=="merge_insertion")merge_insertion_runtime<C>(a,s,v.cutoff);else if(v.family=="quick_insertion")quick_insertion_runtime<C>(a,s,v.cutoff);else if(v.family=="intro_insertion")intro_cutoff_runtime<C>(a,s,v.cutoff);else throw std::runtime_error("unknown family "+v.family);}
static int self_test(){for(auto family:{"merge_insertion","quick_insertion","intro_insertion"})for(std::size_t cutoff:{1U,4U,16U,24U,64U,128U})for(const auto&p:all_patterns())for(std::size_t n:{0U,1U,2U,17U,65U,257U}){auto input=make_data(p,n,trial_seed(7,p,n,3));auto a=input;Stats s;run_variant<false>({family,cutoff},a,s);if(!verify(input,a)){std::cerr<<"FAIL "<<family<<" cutoff="<<cutoff<<" pattern="<<p<<" n="<<n<<'\n';return 1;}}std::cout<<"PASS: cutoff families across deterministic workloads\n";return 0;}
int main(int argc,char**argv){try{bool test=false;int trials=31,warmups=1;std::uint64_t seed=0xC07FFULL;std::vector<std::size_t>sizes={8,12,16,24,32,48,64,96,128,192,256,512,1024,2048,4096,8192};std::vector<std::size_t>cutoffs={1,4,8,12,16,20,24,32,48,64,96,128};std::vector<std::string>families={"merge_insertion","quick_insertion","intro_insertion"};std::vector<std::string>patterns={"random","sorted","few_unique","nearly_sorted","runs"};for(int i=1;i<argc;++i){std::string a=argv[i];if(a=="--self-test")test=true;else if(a=="--trials"&&i+1<argc)trials=std::stoi(argv[++i]);else if(a=="--warmups"&&i+1<argc)warmups=std::stoi(argv[++i]);else if(a=="--seed"&&i+1<argc)seed=std::stoull(argv[++i]);else if(a=="--sizes"&&i+1<argc)sizes=nums(argv[++i]);else if(a=="--cutoffs"&&i+1<argc)cutoffs=nums(argv[++i]);else if(a=="--families"&&i+1<argc)families=split(argv[++i]);else if(a=="--patterns"&&i+1<argc)patterns=split(argv[++i]);else if(a=="--help"){std::cout<<"sort_cutoffs [--trials N] [--warmups N] [--seed N] [--sizes csv] [--cutoffs csv] [--families csv] [--patterns csv]\n";return 0;}else throw std::runtime_error("bad argument: "+a);}if(test)return self_test();if(trials<1||warmups<0)throw std::runtime_error("invalid trial/warmup count");std::vector<Variant>variants;for(const auto&f:families)for(auto c:cutoffs)variants.push_back({f,c});std::cout<<"schema_version,family,cutoff,pattern,n,trial,experiment_seed,trial_seed,input_hash,execution_order,ns,comparisons,swaps,writes,verified\n";for(auto n:sizes)for(const auto&p:patterns){for(int w=0;w<warmups;++w){auto ts=trial_seed(seed^0xA0761D6478BD642FULL,p,n,static_cast<std::uint64_t>(w));auto input=make_data(p,n,ts);for(const auto&v:variants){auto a=input;Stats s;run_variant<false>(v,a,s);if(!verify(input,a))throw std::runtime_error("warmup verify failed");}}for(int t=0;t<trials;++t){auto ts=trial_seed(seed,p,n,static_cast<std::uint64_t>(t));auto input=make_data(p,n,ts);auto fp=input_hash(input);std::vector<std::size_t>order(variants.size());std::iota(order.begin(),order.end(),0);deterministic_shuffle(order,splitmix64(ts^0xD1B54A32D192ED03ULL));struct M{std::size_t idx,ord;std::int64_t ns;Stats stats;};std::vector<M>m;m.reserve(order.size());std::size_t ord=0;for(auto idx:order){auto a=input;Stats s;auto st=std::chrono::steady_clock::now();run_variant<false>(variants[idx],a,s);auto en=std::chrono::steady_clock::now();if(!verify(input,a))throw std::runtime_error("timed verify failed");m.push_back({idx,ord++,std::chrono::duration_cast<std::chrono::nanoseconds>(en-st).count(),{}});}for(auto&x:m){auto a=input;run_variant<true>(variants[x.idx],a,x.stats);if(!verify(input,a))throw std::runtime_error("instrumented verify failed");}for(const auto&x:m){const auto&v=variants[x.idx];std::cout<<1<<','<<v.family<<','<<v.cutoff<<','<<p<<','<<n<<','<<t<<','<<seed<<','<<ts<<','<<fp<<','<<x.ord<<','<<x.ns<<','<<x.stats.comparisons<<','<<x.stats.swaps<<','<<x.stats.writes<<",1\n";}}}return 0;}catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<'\n';return 2;}}
